import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, nowIso, rowToJob, type Job, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1_000_000;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;
const HEARTBEAT_FRESH_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmts = {
  heartbeat: db.prepare('SELECT last_seen FROM worker_heartbeat WHERE id = 1'),
  listJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  getJob: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  findByKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  insertJob: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                       created_at, updated_at, run_after, idempotency_key, payload)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
  ),
};

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function sendMethodNotAllowed(res: ServerResponse, allow: string[]): void {
  res.writeHead(405, { 'content-type': 'application/json; charset=utf-8', allow: allow.join(', ') });
  res.end(JSON.stringify({ error: { code: 'method_not_allowed', message: `Method not allowed. Use ${allow.join(' or ')}.` } }));
}

/** Reads the whole body as UTF-8. Resolves null if it exceeds MAX_BODY_BYTES (the rest is drained). */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Validates an integer field. Returns the value, or the default when absent; records an error otherwise. */
function intField(value: unknown, field: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field, message: `${field} must be an integer from ${min} to ${max}.` });
    return fallback;
  }
  return value;
}

type CreateOutcome = { kind: 'created' | 'replay'; job: Job } | { kind: 'conflict' };

/** Inserts a job, or returns the job already stored under the idempotency key. Serialised by BEGIN IMMEDIATE. */
function createOrReplay(input: string, steps: number, failAttempts: number, key: string | undefined, payload: string): CreateOutcome {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = stmts.findByKey.get(key) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        return existing.payload === payload ? { kind: 'replay', job: rowToJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    stmts.insertJob.run(id, input, steps, failAttempts, now, now, key ?? null, payload);
    const row = stmts.getJob.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { kind: 'created', job: rowToJob(row) };
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // No transaction open; nothing to roll back.
    }
    throw err;
  }
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const fields: FieldError[] = [];

  const contentType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let parsed: Record<string, unknown> | undefined;
  if (contentType !== 'application/json') {
    fields.push(
      { field: 'Content-Type', message: 'Content-Type must be application/json.' },
      { field: 'body', message: 'Request body must be JSON sent with Content-Type application/json.' },
    );
  } else if (body === null) {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    let value: unknown;
    let parsedOk = false;
    try {
      value = JSON.parse(body);
      parsedOk = true;
    } catch {
      fields.push({ field: 'body', message: 'Request body is not valid JSON.' });
    }
    if (parsedOk) {
      if (isPlainObject(value)) parsed = value;
      else fields.push({ field: 'body', message: 'Request body must be a JSON object.' });
    }
  }

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must be 1 to 128 characters: letters, digits, "_" or "-".' });
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (parsed) {
    for (const name of Object.keys(parsed)) {
      if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'Unknown field.' });
    }
    const rawInput = parsed.input;
    if (rawInput === undefined) {
      fields.push({ field: 'input', message: 'input is required.' });
    } else if (typeof rawInput !== 'string' || rawInput.length < 1 || rawInput.length > 1000 || rawInput.trim() === '') {
      fields.push({ field: 'input', message: 'input must be a string of 1 to 1000 characters that is not only whitespace.' });
    } else {
      input = rawInput;
    }
    steps = intField(parsed.steps, 'steps', 1, 20, 5, fields);
    failAttempts = intField(parsed.failAttempts, 'failAttempts', 0, 5, 0, fields);
  }

  if (fields.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }

  const payload = JSON.stringify({ input, steps, failAttempts });
  const outcome = createOrReplay(input, steps, failAttempts, key, payload);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  } else if (outcome.kind === 'replay') {
    send(res, 200, outcome.job);
  } else {
    send(res, 201, outcome.job);
  }
}

function handleHealth(res: ServerResponse): void {
  const hb = stmts.heartbeat.get() as unknown as { last_seen: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.last_seen < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function handleGetJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  const row = stmts.getJob.get(id) as unknown as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  send(res, 200, rowToJob(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    return handleHealth(res);
  }

  if (pathname === '/') {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const jobs = (stmts.listJobs.all() as unknown as JobRow[]).map(rowToJob);
      return send(res, 200, { jobs });
    }
    if (method === 'POST') return handleCreateJob(req, res);
    return sendMethodNotAllowed(res, ['GET', 'POST']);
  }

  const match = JOB_PATH_RE.exec(pathname);
  if (match) {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    return handleGetJob(res, match[1]!);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Unexpected server error.');
    }
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  setTimeout(() => process.exit(0), 2000).unref();
  server.close();
  server.closeAllConnections();
  db.close();
  process.exit(0);
}
for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, shutdown);
}

