import { setTimeout as sleep } from 'node:timers/promises';
import { nowIso, openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_MS = 200;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const HEARTBEAT_MS = 1000;
const FORCE_EXIT_MS = 3000;

const db = openDatabase();
let stopping = false;

const stmts = {
  heartbeat: db.prepare(
    'INSERT INTO worker_heartbeat (id, last_seen) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen',
  ),
  // Atomically take the oldest due queued job and mark it running for a new attempt.
  claim: db.prepare(
    `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, error = NULL, updated_at = ?
     WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
     RETURNING *`,
  ),
  progress: db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`),
  complete: db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ),
  fail: db.prepare(
    `UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ),
  retryLater: db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ),
  requeueOne: db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ?
